-- gerado por /tmp/opencode/sfia9_views_attrs_sql.py
-- arvore de views SFIA (12 dominios, sub-views, folhas) + 16 atributos genericos x 7 niveis
BEGIN;
SET search_path = esco_dataset, public;

CREATE TABLE IF NOT EXISTS sfia_atributo
(
	slug TEXT PRIMARY KEY,
	codigo TEXT,
	nome_en TEXT,
	nome_pt TEXT
);
CREATE TABLE IF NOT EXISTS sfia_atributo_nivel
(
	slug TEXT NOT NULL REFERENCES sfia_atributo(slug) ON DELETE CASCADE,
	nivel SMALLINT NOT NULL REFERENCES nivel_habilidade(nivel) ON DELETE CASCADE,
	descricao_en TEXT,
	descricao_pt TEXT,
	PRIMARY KEY (slug, nivel)
);
CREATE TABLE IF NOT EXISTS sfia_view
(
	view_id SERIAL PRIMARY KEY,
	caminho TEXT NOT NULL UNIQUE,
	slug TEXT,
	slug_pai TEXT,
	nome_en TEXT,
	nome_pt TEXT,
	profundidade SMALLINT
);
CREATE TABLE IF NOT EXISTS sfia_view_habilidade
(
	caminho TEXT NOT NULL REFERENCES sfia_view(caminho) ON DELETE CASCADE,
	habilidade_id INTEGER NOT NULL REFERENCES habilidade(habilidade_id) ON DELETE CASCADE,
	PRIMARY KEY (caminho, habilidade_id)
);

ON CONFLICT (slug) DO UPDATE SET codigo = EXCLUDED.codigo, nome_en = EXCLUDED.nome_en, nome_pt = EXCLUDED.nome_pt;

ON CONFLICT (slug, nivel) DO UPDATE SET descricao_en = EXCLUDED.descricao_en, descricao_pt = EXCLUDED.descricao_pt;
ON CONFLICT (slug, nivel) DO UPDATE SET descricao_en = EXCLUDED.descricao_en, descricao_pt = EXCLUDED.descricao_pt;

ON CONFLICT (caminho) DO UPDATE SET slug = EXCLUDED.slug, slug_pai = EXCLUDED.slug_pai, nome_en = EXCLUDED.nome_en, nome_pt = EXCLUDED.nome_pt, profundidade = EXCLUDED.profundidade;

-- vínculos view x habilidade (folhas e sub-views que listam skills)
ON CONFLICT DO NOTHING;
ON CONFLICT DO NOTHING;
ON CONFLICT DO NOTHING;
ON CONFLICT DO NOTHING;
ON CONFLICT DO NOTHING;
ON CONFLICT DO NOTHING;
ON CONFLICT DO NOTHING;
ON CONFLICT DO NOTHING;

COMMIT;
