INSERT INTO sfia_atributo (slug, codigo, nome_en, nome_pt) VALUES
('adaptability', 'ADAP', 'Adaptability', 'Adaptabilidade'),
('autonomy', 'AUTO', 'Autonomy', 'Autonomia'),
('collaboration', 'COLL', 'Collaboration', 'Colaboração'),
('communication', 'COMM', 'Communication', 'Comunicação'),
('complexity', 'COMP', 'Complexity', 'Complexidade'),
('creativity', 'CRTY', 'Creativity', 'Criatividade'),
('decision', 'DECM', 'Decision-making', 'Tomada de Decisão'),
('digital_mindset', 'DIGI', 'Digital mindset', 'Mentalidade digital'),
('improvement', 'IMPM', 'Improvement mindset', 'Mentalidade de melhoria'),
('influence', 'INFL', 'Influence', 'Influência'),
('knowledge', 'KNGE', 'Knowledge', 'Conhecimento'),
('leadership', 'LEAD', 'Leadership', 'Liderança'),
('learning', 'LADV', 'Learning and development', 'Aprendizagem e desenvolvimento'),
('planning', 'PLAN', 'Planning', 'Planejamento'),
('problem', 'PROB', 'Problem-solving', 'Resolução de Problemas'),
('security', 'SCPE', 'Security, privacy and ethics', 'Segurança, privacidade e ética')
INSERT INTO sfia_atributo_nivel (slug, nivel, descricao_en, descricao_pt) VALUES
('adaptability', 1, 'Accepts change and is open to new ways of working.', 'Aceita mudanças e está aberto a novas formas de trabalho.'),
('adaptability', 2, 'Adjusts to different team dynamics and work requirements. Participates in team adaptation processes.', 'Ajusta-se a diferentes dinâmicas de equipe e requisitos de trabalho. Participa dos processos de adaptação da equipe.'),
('adaptability', 3, 'Adapts and is responsive to change and shows initiative in adopting new methods or technologies.', 'Adapta-se e reage às mudanças e demonstra iniciativa na adoção de novos métodos ou tecnologias.'),
('adaptability', 4, 'Enables others to adapt and change in response to challenges and changes in the work environment.', 'Permite que outras pessoas se adaptem e mudem em resposta a desafios e mudanças no ambiente de trabalho.'),
('adaptability', 5, 'Leads adaptations to changing business environments. Guides teams through transitions, maintaining focus on organisational objectives.', 'Lidera adaptações a ambientes de negócios em constante mudança. Orienta as equipes durante as transições, mantendo o foco nos objetivos organizacionais.'),
('adaptability', 6, 'Drives organisational adaptability by initiating and leading significant changes. Influences change management strategies at an organisational level.', 'Promove a adaptabilidade organizacional ao iniciar e liderar mudanças significativas. Influencia as estratégias de gerenciamento de mudanças em nível organizacional.'),
('adaptability', 7, 'Champions organisational agility and resilience. Embeds adaptability into organisational culture and strategic planning. SFIA week announcement SFIA week 2026 - a diverse programme of free to attend activities and events created to help you SFIA version 9 Framework status: Current standard', 'Promove a agilidade e a resiliência organizacional. Incorpora a adaptabilidade à cultura organizacional e ao planejamento estratégico. Versão SFIA 9 Status da estrutura: Padrão atual'),
('autonomy', 1, 'Follows instructions and works under close direction. Receives specific instructions and guidance, has work closely reviewed.', 'Segue as instruções e trabalha sob orientação rigorosa. Recebe instruções e orientações específicas e tem seu trabalho revisado de perto.'),
('autonomy', 2, 'Works under routine direction. Receives instructions and guidance, has work regularly reviewed.', 'Trabalha sob direção rotineira. Recebe instruções e orientações e tem seu trabalho revisado regularmente.'),
('autonomy', 3, 'Works under general direction to complete assigned tasks. Receives guidance and has work reviewed at agreed milestones. When required, delegates routine tasks to others within own team.', 'Trabalha sob direção geral para concluir as tarefas atribuídas. Recebe orientação e tem o trabalho revisado nos marcos acordados. Quando necessário, delega tarefas de rotina a outras pessoas da própria equipe.'),
('autonomy', 4, 'Works under general direction within a clear framework of accountability. Exercises considerable personal responsibility and autonomy. When required, plans, schedules, and delegates work to others, typically within own team.', 'Trabalha sob direção geral dentro de uma estrutura clara de responsabilidade. Exerce considerável responsabilidade pessoal e autonomia. Quando necessário, planeja, agenda e delega trabalho a outras pessoas, geralmente dentro da própria equipe.'),
('autonomy', 5, 'Works under broad direction. Work is self-initiated, consistent with agreed operational and budgetary requirements for meeting allocated technical and/or group objectives. Defines tasks and delegates work to teams and individuals within area of responsibility.', 'Trabalha sob ampla direção. O trabalho é de iniciativa própria, consistente com os requisitos operacionais e orçamentários acordados para atender aos objetivos técnicos e/ou de grupo alocados. Define tarefas e delega trabalho a equipes e indivíduos dentro da sua área de responsabilidade.'),
('autonomy', 6, 'Guides high level decisions and strategies within the organisation’s overall policies and objectives. Has defined authority and accountability for actions and decisions within a significant area of work, including technical, financial and quality aspects. Delegates responsibility for operational objectives.', 'Orienta decisões e estratégias de alto nível dentro das políticas e dos objetivos gerais da organização. Tem autoridade e responsabilidade definidas para ações e decisões em uma área significativa de trabalho, incluindo aspectos técnicos, financeiros e de qualidade. Delega a responsabilidade pelos objetivos operacionais.'),
('autonomy', 7, 'Defines and leads the organisation’s vision and strategy within over-arching business objectives. Is fully accountable for actions taken and decisions made, both by self and others to whom responsibilities have been assigned. Delegates authority and responsibility for strategic business objectives. SFIA week announcement SFIA week 2026 - a diverse programme of free to attend activities and events created to help you SFIA version 9 Framework status: Current standard', 'Define e lidera a visão e a estratégia da organização dentro dos objetivos comerciais mais abrangentes. É totalmente responsável pelas ações e decisões tomadas, tanto por si mesmo quanto por outros a quem foram atribuídas responsabilidades. Delega autoridade e responsabilidade pelos objetivos estratégicos do negócio. Versão SFIA 9 Status da estrutura: Padrão atual'),
('collaboration', 1, 'Works mostly on their own tasks and interacts with their immediate team only. Develops an understanding of how their work supports others.', 'Trabalha principalmente em suas próprias tarefas e interage apenas com sua equipe imediata. Desenvolve a compreensão de como seu trabalho ajuda os outros.'),
('collaboration', 2, 'Understands the need to collaborate with their team and considers user/customer needs.', 'Compreende a necessidade de colaborar com sua equipe e considera as necessidades do usuário/cliente.'),
('collaboration', 3, 'Understands and collaborates on the analysis of user/customer needs and represents this in their work.', 'Compreende e colabora com a análise das necessidades do usuário/cliente e representa isso em seu trabalho.'),
('collaboration', 4, 'Facilitates collaboration between stakeholders who share common objectives. Engages with and contributes to the work of cross-functional teams to ensure that user/customer needs are being met throughout the deliverable/scope of work.', 'Facilita a colaboração entre as partes interessadas que compartilham objetivos comuns. Envolve-se e contribui para o trabalho de equipes multifuncionais para garantir que as necessidades do usuário/cliente sejam atendidas em todo o produto/escopo de trabalho.'),
('collaboration', 5, 'Facilitates collaboration between stakeholders who have diverse objectives. Ensures collaborative ways of working throughout all stages of work to meet user/customer needs. Builds effective relationships across the organisation and with customers, suppliers and partners.', 'Facilita a colaboração entre as partes interessadas que têm objetivos diferentes. Garante formas colaborativas de trabalho em todos os estágios do trabalho para atender às necessidades do usuário/cliente. Estabelece relacionamentos eficazes em toda a organização e com clientes, fornecedores e parceiros.'),
('collaboration', 6, 'Leads collaboration with a diverse range of stakeholders across competing objectives within the organisation. Builds strong, influential connections with key internal and external contacts at senior management/technical leader level', 'Lidera a colaboração com uma gama diversificada de partes interessadas em objetivos concorrentes dentro da organização. Estabelece conexões fortes e influentes com os principais contatos internos e externos em nível de gerência sênior/líder técnico'),
('collaboration', 7, 'Drives collaboration, engaging with leadership stakeholders ensuring alignment to corporate vision and strategy. Builds strong, influential relationships with customers, partners and industry leaders. SFIA week announcement SFIA week 2026 - a diverse programme of free to attend activities and events created to help you SFIA version 9 Framework status: Current standard', 'Promove a colaboração, envolvendo-se com as partes interessadas da liderança, garantindo o alinhamento com a visão e a estratégia corporativas. Estabelece relacionamentos sólidos e influentes com clientes, parceiros e líderes do setor. Versão SFIA 9 Status da estrutura: Padrão atual'),
('communication', 1, 'Communicates with immediate team to understand and deliver on their assigned tasks. Observes, listens, and with encouragement, asks questions to seek information or clarify instructions.', 'Comunica-se com a equipe imediata para entender e cumprir as tarefas atribuídas. Observa, ouve e faz perguntas para buscar informações ou esclarecer instruções.'),
('communication', 2, 'Communicates familiar information with immediate team and stakeholders directly related to their role. Listens to gain understanding and asks relevant questions to clarify or seek further information.', 'Comunica informações à equipe imediata e às partes interessadas diretamente relacionadas à sua função. Ouve para obter compreensão e faz perguntas relevantes para esclarecer ou buscar mais informações.'),
('communication', 3, 'Communicates with team and stakeholders inside and outside the organisation clearly explaining and presenting information. Contributes to a range of work-related conversations and listens to others to gain an understanding and asks probing questions relevant to their role.', 'Comunica-se com a equipe e as partes interessadas dentro e fora da organização, explicando e apresentando as informações com clareza. Contribui para uma série de conversas relacionadas ao trabalho, ouve os outros para obter entendimento e faz perguntas relevantes para sua função.'),
('communication', 4, 'Communicates with both technical and non-technical audiences including team and stakeholders inside and outside the organisation. As required, takes the lead in explaining complex concepts to support decision making. Listens and asks insightful questions to identify different perspectives to clarify and confirm understanding.', 'Comunica-se com públicos técnicos e não técnicos, incluindo a equipe e as partes interessadas dentro e fora da organização. Conforme necessário, assume a liderança na explicação de conceitos complexos para apoiar a tomada de decisões. Ouve e faz perguntas perspicazes para identificar diferentes perspectivas e esclarecer e confirmar o entendimento.'),
('communication', 5, 'Communicates clearly with impact, articulating complex information and ideas to broad audiences with different viewpoints. Leads and encourages conversations to share ideas and build consensus on actions to be taken.', 'Comunica-se com clareza e impacto, articulando informações e ideias complexas para públicos amplos com diferentes pontos de vista. Lidera e incentiva conversas para compartilhar ideias e criar consenso sobre as ações a serem tomadas.'),
('communication', 6, 'Communicates with credibility at all levels across the organisation to broad audiences with divergent objectives. Explains complex information and ideas clearly, influencing the strategic direction. Promotes information sharing across the organisation.', 'Comunica-se com credibilidade em todos os níveis da organização para públicos amplos com objetivos divergentes. Explica informações e ideias complexas com clareza, influenciando a direção estratégica. Promove o compartilhamento de informações em toda a organização.'),
('communication', 7, 'Communicates to audiences at all levels within own organisation and engages with industry. Presents compelling arguments and ideas authoritatively and convincingly to achieve business objectives. SFIA week announcement SFIA week 2026 - a diverse programme of free to attend activities and events created to help you SFIA version 9 Framework status: Current standard', 'Comunica-se com o público em todos os níveis da própria organização e se envolve com o setor. Apresenta argumentos e ideias convincentes de forma objetiva para atingir os objetivos de negócio. Versão SFIA 9 Status da estrutura: Padrão atual'),
('complexity', 1, 'Performs routine activities in a structured environment.', 'Realiza atividades de rotina em um ambiente estruturado.'),
('complexity', 2, 'Performs a range of work activities in varied environments.', 'Realiza uma série de atividades de trabalho em ambientes variados.'),
('complexity', 3, 'Performs a range of work, sometimes complex and non-routine, in varied environments.', 'Realiza uma série de trabalhos, às vezes complexos e não rotineiros, em ambientes variados.'),
('complexity', 4, 'Work includes a broad range of complex technical or professional activities in varied contexts.', 'O trabalho inclui uma ampla gama de atividades técnicas ou profissionais complexas em contextos variados.'),
('complexity', 5, 'Performs an extensive range of complex technical and/or professional work activities, requiring the application of fundamental principles in a range of unpredictable contexts.', 'Executa uma ampla gama de atividades de trabalho técnicas e/ou profissionais complexas, exigindo a aplicação de princípios fundamentais em uma variedade de contextos imprevisíveis.'),
('complexity', 6, 'Performs highly complex work activities covering technical, financial and quality aspects.', 'Realiza atividades de trabalho altamente complexas que abrangem aspectos técnicos, financeiros e de qualidade.'),
('complexity', 7, 'Performs extensive strategic leadership in delivering business value through vision, governance and executive management. SFIA week announcement SFIA week 2026 - a diverse programme of free to attend activities and events created to help you SFIA version 9 Framework status: Current standard', 'Exerce ampla liderança estratégica na entrega de valor comercial por meio de visão, governança e gerenciamento executivo. Versão SFIA 9 Status da estrutura: Padrão atual'),
('creativity', 1, 'Participates in the generation of new ideas when prompted.', 'Participa da geração de novas ideias quando solicitado.'),
('creativity', 2, 'Applies creative thinking to suggest new ways to approach a task and solve problems.', 'Aplica o pensamento criativo para sugerir novas maneiras de abordar uma tarefa e resolver problemas.'),
('creativity', 3, 'Applies and contributes to creative thinking techniques to contribute new ideas for their own work and for team activities.', 'Aplica e contribui com técnicas de pensamento criativo para contribuir com novas ideias para seu próprio trabalho e para as atividades da equipe.'),
('creativity', 4, 'Applies, facilitates and develops creative thinking concepts and finds alternative ways to approach team outcomes.', 'Aplica, facilita e desenvolve conceitos de pensamento criativo e encontra maneiras alternativas de abordar os resultados da equipe.'),
('creativity', 5, 'Creatively applies innovative thinking and design practices in identifying solutions that will deliver value for the benefit of the customer/stakeholder.', 'Aplica de forma criativa o pensamento inovador e práticas de design na identificação de soluções que agregarão valor para o benefício do cliente/stakeholder.'),
('creativity', 6, 'Creatively applies a wide range of new ideas and effective management techniques to achieve results that align with organisational strategy.', 'Aplica com criatividade uma ampla gama de novas ideias e técnicas de gerenciamento eficazes para obter resultados que se alinham à estratégia organizacional.'),
('creativity', 7, 'Champions creativity and innovation in driving strategy development to enable business opportunities. SFIA week announcement SFIA week 2026 - a diverse programme of free to attend activities and events created to help you SFIA version 9 Framework status: Current standard', 'Defende a criatividade e a inovação como incentivadoras do desenvolvimento da estratégia para proporcionar oportunidades de negócio. Versão SFIA 9 Status da estrutura: Padrão atual'),
('decision', 1, 'Uses little discretion in attending to enquiries. Is expected to seek guidance in unexpected situations.', 'Tem pouca liberdade no atendimento a consultas. Busca orientação em situações inesperadas.'),
('decision', 2, 'Uses limited discretion in resolving issues or enquiries. Decides when to seek guidance in unexpected situations.', 'Tem liberdade limitada na resolução de problemas ou consultas. Decide quando buscar orientação em situações inesperadas.'),
('decision', 3, 'Uses discretion in identifying and responding to complex issues related to own assignments. Determines when issues should be escalated to a higher level.', 'Tem liberdade para identificar e responder a questões complexas relacionadas às suas próprias atribuições. Determina quando os problemas devem ser escalados para um nível superior.'),
('decision', 4, 'Uses judgment and substantial discretion in identifying and responding to complex issues and assignments related to projects and team objectives. Escalates when scope is impacted.', 'Julga e possui liberdade substancial para identificar e responder a questões e atribuições complexas relacionadas a projetos e objetivos de equipe. Escalona quando o escopo é afetado.'),
('decision', 5, 'Uses judgement to make informed decisions on actions to achieve organisational outcomes such as meeting targets, deadlines, and budget. Raises issues when objectives are at risk.', 'Usa o discernimento para tomar decisões informadas sobre ações para atingir os resultados organizacionais, como o cumprimento de metas, prazos e orçamento. Levanta questões quando os objetivos estão em risco.'),
('decision', 6, 'Uses judgement to make decisions that initiate the achievement of agreed strategic objectives including financial performance. Escalates when broader strategic direction is impacted.', 'Usa o discernimento para tomar decisões que iniciam a realização dos objetivos estratégicos acordados, incluindo o desempenho financeiro. Escalona quando a direção estratégica mais ampla é afetada.'),
('decision', 7, 'Uses judgement in making decisions critical to the organisational strategic direction and success. Escalates when business executive management input is required through established governance structures. SFIA week announcement SFIA week 2026 - a diverse programme of free to attend activities and events created to help you SFIA version 9 Framework status: Current standard', 'Usa o discernimento na tomada de decisões essenciais para a direção estratégica e o sucesso da organização. Encaminha, quando necessário, a contribuição da gerência executiva da empresa por meio de estruturas de governança estabelecidas. Versão SFIA 9 Status da estrutura: Padrão atual'),
('digital_mindset', 1, 'Has basic digital skills to learn and use applications, processes and tools for their role.', 'Possui habilidades digitais básicas para aprender e usar aplicativos, processos e ferramentas para sua função.'),
('digital_mindset', 2, 'Has sufficient digital skills for their role; understands and uses appropriate methods, tools, applications and processes.', 'Possui habilidades digitais suficientes para sua função; compreende e usa métodos, ferramentas, aplicativos e processos adequados.'),
('digital_mindset', 3, 'Explores and applies relevant digital tools and skills for their role. Understands and effectively applies appropriate methods, tools, applications and processes.', 'Explora e aplica ferramentas e habilidades digitais relevantes para sua função. Compreende e usa de maneira eficaz os métodos, ferramentas, aplicativos e processos apropriados.'),
('digital_mindset', 4, 'Maximises the capabilities of applications for their role and evaluates and supports the use of new technologies and digital tools. Selects appropriately from, and assesses the impact of change to applicable standards, methods, tools, applications and processes relevant to own specialism.', 'Maximiza as capacidades das aplicações para o seu papel, avalia e apoia a utilização de novas tecnologias e ferramentas digitais. Seleciona adequadamente e avalia o impacto da mudança nos padrões, métodos, ferramentas, aplicativos e processos aplicáveis relevantes à própria especialidade.'),
('digital_mindset', 5, 'Recognises and evaluates the organisational impact of new technologies and digital services. Implements new and effective practices. Advises on available standards, methods, tools, applications and processes relevant to group specialism(s) and can make appropriate choices from alternatives.', 'Reconhece e avalia o impacto organizacional de novas tecnologias e serviços digitais. Implementa práticas novas e eficazes. Aconselha sobre os padrões, métodos, ferramentas, aplicações e processos disponíveis relevantes para a(s) especialidade(s) do grupo e pode fazer escolhas apropriadas entre alternativas.'),
('digital_mindset', 6, 'Leads the enhancement of the organisation’s digital capabilities. Identifies and endorses opportunities to adopt new technologies and digital services. Leads digital governance and compliance with relevant legislation and the need for products and services.', 'Lidera o aprimoramento dos recursos digitais da organização. Identifica e endossa oportunidades para adotar novas tecnologias e serviços digitais. Lidera a governança digital e a conformidade com a legislação pertinente e a necessidade de produtos e serviços.'),
('digital_mindset', 7, 'Leads the development of the organisation’s digital culture and the transformational vision. Advances capability and/or exploitation of technology within one or more organisations through a deep understanding of the industry and the implications of emerging technologies. Accountable for assessing how laws and regulations impact organisational objectives and its use of digital, data and technology capabilities. SFIA week announcement SFIA week 2026 - a diverse programme of free to attend activities and events created to help you SFIA version 9 Framework status: Current standard', 'Lidera o desenvolvimento da cultura digital da organização e a visão transformacional. Aumenta a capacidade e/ou a exploração da tecnologia em uma ou mais organizações por meio de um profundo entendimento do setor e das implicações das tecnologias emergentes. Responsabiliza-se por avaliar como as leis e os regulamentos afetam os objetivos organizacionais e seu uso de recursos digitais, de dados e de tecnologia. Versão SFIA 9 Status da estrutura: Padrão atual'),
('improvement', 1, 'Identifies opportunities for improvement in own tasks. Suggests basic enhancements when prompted.', 'Identifica oportunidades de melhoria em suas próprias tarefas. Sugere aprimoramentos básicos quando solicitado.'),
('improvement', 2, 'Proposes ideas to improve own work area. Implements agreed changes to assigned work tasks.', 'Propõe ideias para melhorar a própria área de trabalho. Implementa as alterações acordadas nas tarefas de trabalho atribuídas.'),
('improvement', 3, 'Identifies and implements improvements in own work area. Contributes to team-level process enhancements.', 'Identifica e implementa melhorias em sua própria área de trabalho. Contribui para aprimoramentos de processos da equipe.'),
('improvement', 4, 'Encourages and supports team discussions on improvement initiatives. Implements procedural changes within a defined scope of work.', 'Incentiva e apoia as discussões da equipe sobre iniciativas de melhoria. Implementa mudanças processuais em um escopo de trabalho definido.'),
('improvement', 5, 'Identifies and evaluates potential improvements to products, practices, or services. Leads implementation of enhancements within own area of responsibility. Assesses effectiveness of implemented changes.', 'Identifica e avalia possíveis melhorias em produtos, práticas ou serviços. Lidera a implementação de aprimoramentos em sua própria área de responsabilidade. Avalia a eficácia das mudanças implementadas.'),
('improvement', 6, 'Drives improvement initiatives that have a significant impact on the organisation. Aligns improvement strategies with organisational objectives. Engages stakeholders in improvement processes.', 'Promove iniciativas de melhoria que têm um impacto significativo na organização. Alinha as estratégias de aprimoramento com os objetivos organizacionais. Envolve as partes interessadas nos processos de aprimoramento.'),
('improvement', 7, 'Defines and communicates the organisational approach to continuous improvement. Cultivates a culture of ongoing enhancement. Evaluates the impact of improvement initiatives on organisational success. SFIA week announcement SFIA week 2026 - a diverse programme of free to attend activities and events created to help you SFIA version 9 Framework status: Current standard', 'Define e comunica a abordagem organizacional para a melhoria contínua. Cultiva uma cultura de aprimoramento contínuo. Avalia o impacto das iniciativas de melhoria no sucesso organizacional. Versão SFIA 9 Status da estrutura: Padrão atual'),
('influence', 1, 'When required, contributes to team discussions with immediate colleagues.', 'Quando necessário, contribui para discussões de equipe com colegas imediatos.'),
('influence', 2, 'Is expected to contribute to team discussions with immediate team members. Works alongside team members, contributing to team decisions. When the role requires, interacts with people outside their team, including internal colleagues and external contacts.', 'Contribui para as discussões com os membros da equipe. Trabalha ao lado dos membros da equipe, contribuindo para as decisões da equipe. Quando a função exige, interage com pessoas de fora da equipe, incluindo colegas internos e contatos externos.'),
('influence', 3, 'Works with and influences team decisions. Has a transactional level of contact with people outside their team, including internal colleagues and external contacts.', 'Trabalha com a equipe e influencia suas decisões. Tem um nível transacional de contato com pessoas de fora da equipe, incluindo colegas internos e contatos externos.'),
('influence', 4, 'Influences projects and team objectives. Has a tactical level of contact with people outside their team, including internal colleagues and external contacts.', 'Influencia os projetos e os objetivos da equipe. Tem um nível tático de contato com pessoas de fora da equipe, incluindo colegas internos e contatos externos.'),
('influence', 5, 'Influences critical decisions in their domain. Has operational level contact impacting execution and implementation with internal colleagues and external contacts. Has significant influence over the allocation and management of resources required to deliver projects.', 'Influencia decisões críticas em seu domínio. Tem contato de nível operacional que afeta a execução e a implementação com colegas internos e contatos externos. Tem influência significativa sobre a alocação e o gerenciamento dos recursos necessários para a execução dos projetos.'),
('influence', 6, 'Influences the formation of strategy and the execution of business plans. Has a significant management level of contact with internal colleagues and external contacts. Has organisational leadership and influence over the appointment and management of resources related to the implementation of strategic initiatives.', 'Influencia a formação da estratégia e a execução dos planos de negócios. Tem um nível gerencial significativo de contato com colegas internos e contatos externos. Exerce liderança organizacional e influência sobre a nomeação e o gerenciamento de recursos relacionados à implementação de iniciativas estratégicas.'),
('influence', 7, 'Directs, influences and inspires the strategic direction and development of the organisation. Has an extensive leadership level of contact with internal colleagues and external contacts. Authorises the appointment of required resources. SFIA week announcement SFIA week 2026 - a diverse programme of free to attend activities and events created to help you SFIA version 9 Framework status: Current standard', 'Dirige, influencia e inspira a direção estratégica e o desenvolvimento da organização. Tem um nível de liderança extensivo de contato com colegas internos e contatos externos. Autoriza a nomeação dos recursos necessários. Versão SFIA 9 Status da estrutura: Padrão atual'),
('knowledge', 1, 'Applies basic knowledge to perform routine, well-defined, predictable role-specific tasks.', 'Aplica conhecimentos básicos para executar tarefas rotineiras, bem definidas e previsíveis, específicas da função.'),
('knowledge', 2, 'Applies knowledge of common workplace tasks and practices to support team activities under guidance.', 'Aplica o conhecimento das tarefas e práticas comuns do local de trabalho para apoiar as atividades da equipe, sob orientação.'),
('knowledge', 3, 'Applies knowledge of a range of role-specific practices to complete tasks within defined boundaries and has an appreciation of how this knowledge applies to the wider business context.', 'Aplica o conhecimento de uma série de práticas específicas da função para concluir tarefas dentro de limites definidos e avalia como esse conhecimento se aplica ao contexto comercial mais amplo.'),
('knowledge', 4, 'Applies knowledge across different areas in their field, integrating this knowledge to perform complex and diverse tasks. Applies a working knowledge of the organisation’s domain.', 'Aplica conhecimento em diferentes áreas de seu campo, integrando esse conhecimento para realizar tarefas complexas e diversas. Aplica o conhecimento prático do domínio da organização.'),
('knowledge', 5, 'Applies knowledge to interpret complex situations and offer authoritative advice. Applies in-depth expertise in specific fields, with a broader understanding across industry/business.', 'Aplica o conhecimento para interpretar situações complexas e oferecer conselhos com autoridade. Aplica conhecimentos profundos em campos específicos, com uma compreensão mais ampla do setor/negócio.'),
('knowledge', 6, 'Applies broad business knowledge to enable strategic leadership and decision-making across various domains.', 'Aplica amplo conhecimento comercial para permitir a liderança estratégica e a tomada de decisões em vários domínios.'),
('knowledge', 7, 'Applies strategic and broad-based knowledge to shape organisational strategy, anticipate future industry trends, and prepare the organisation to adapt and lead. SFIA week announcement SFIA week 2026 - a diverse programme of free to attend activities and events created to help you SFIA version 9 Framework status: Current standard', 'Aplica conhecimentos estratégicos e de base ampla para moldar a estratégia organizacional, prever tendências futuras do setor e preparar a organização para se adaptar e liderar. Versão SFIA 9 Status da estrutura: Padrão atual'),
('leadership', 1, 'Proactively increases their understanding of their work tasks and responsibilities.', 'Aumenta proativamente a compreensão de suas tarefas e responsabilidades no trabalho.'),
('leadership', 2, 'Takes ownership to develop their work experience.', 'Assume a responsabilidade pelo desenvolvimento de sua experiência de trabalho.'),
('leadership', 3, 'Provides basic guidance and support to less experienced team members as needed.', 'Fornece orientação básica e suporte a membros menos experientes da equipe, conforme necessário.'),
('leadership', 4, 'Leads, supports or guides team members. Develops solutions for complex work activities related to assignments. Demonstrates an understanding of risk factors in their work. Contributes specialist expertise to requirements definition in support of proposals.', 'Lidera, apoia ou orienta os membros da equipe. Desenvolve soluções para atividades de trabalho complexas relacionadas a atribuições. Demonstra compreensão dos fatores de risco em seu trabalho. Contribui com conhecimento especializado para a definição de requisitos em apoio a propostas.'),
('leadership', 5, 'Provides leadership at an operational level. Implements and executes policies aligned to strategic plans. Assesses and evaluates risk. Takes all requirements into account when considering proposals.', 'Oferece liderança em nível operacional. Implementa e executa políticas alinhadas aos planos estratégicos. Analisa e avalia riscos. Leva em conta todos os requisitos ao considerar as propostas.'),
('leadership', 6, 'Provides leadership at an organisational level. Contributes to the development and implementation of policy and strategy. Understands and communicates industry developments, and the role and impact of technology. Manages and mitigates organisational risk. Balances the requirements of proposals with the broader needs of the organisation.', 'Oferece liderança em nível organizacional. Contribui para o desenvolvimento e a implementação de políticas e estratégias. Compreende e comunica os desenvolvimentos da indústria e o papel e o impacto da tecnologia. Gerencia e mitiga o risco organizacional. Equilibra os requisitos das propostas com as necessidades mais amplas da organização.'),
('leadership', 7, 'Leads strategic management. Applies the highest level of leadership to the formulation and implementation of strategy. Communicates the potential impact of emerging practices and technologies on organisations and individuals and assesses the risks of using or not using such practices and technologies. Establishes governance to address business risk. Ensures proposals align with the strategic direction of the organisation. SFIA week announcement SFIA week 2026 - a diverse programme of free to attend activities and events created to help you SFIA version 9 Framework status: Current standard', 'Lidera o gerenciamento estratégico. Aplica o mais alto nível de liderança à formulação e implementação da estratégia. Comunica o impacto potencial das práticas emergentes e tecnologias sobre as organizações e indivíduos, e avalia os riscos de usar ou não usar tais práticas e tecnologias. Estabelece governança para tratar dos riscos do negócio. Garante que as propostas se alinhem à direção estratégica da organização. Versão SFIA 9 Status da estrutura: Padrão atual'),
('learning', 1, 'Applies newly acquired knowledge to develop skills for their role. Contributes to identifying own development opportunities.', 'Aplica o conhecimento recém-adquirido para desenvolver habilidades para sua função. Contribui para identificar as próprias oportunidades de desenvolvimento.'),
('learning', 2, 'Absorbs and applies new information to tasks. Recognises personal skills and knowledge gaps and seeks learning opportunities to address them.', 'Absorve e aplica novas informações às tarefas. Reconhece as habilidades pessoais e as lacunas de conhecimento e busca oportunidades de aprendizado para resolvê-las.'),
('learning', 3, 'Absorbs and applies new information effectively with the ability to share learnings with colleagues. Takes the initiative in identifying and negotiating their own appropriate development opportunities.', 'Absorve e aplica novas informações de forma eficaz, com a capacidade de compartilhar o aprendizado com os colegas. Toma a iniciativa de identificar e negociar suas próprias oportunidades de desenvolvimento apropriadas.'),
('learning', 4, 'Rapidly absorbs and critically assesses new information and applies it effectively. Maintains an understanding of emerging practices and their application and takes responsibility for driving own and team members’ development opportunities.', 'Absorve rapidamente e avalia criticamente novas informações e as aplica de forma eficaz. Mantém um entendimento das práticas emergentes e de sua aplicação e assume a responsabilidade de promover oportunidades de desenvolvimento para si mesmo e para os membros da equipe.'),
('learning', 5, 'Uses their skills and knowledge to help establish the standards that others in the organisation will apply. Takes the initiative to develop a wider breadth of knowledge across industry and/or business and identify and manage development opportunities in area of responsibility.', 'Usa suas habilidades e conhecimentos para ajudar a estabelecer os padrões que serão aplicados por outras pessoas na organização. Toma a iniciativa de desenvolver um conhecimento mais amplo do setor e/ou da empresa e de identificar e gerenciar oportunidades de desenvolvimento na área de responsabilidade.'),
('learning', 6, 'Promotes the application of knowledge to support strategic imperatives. Actively develops their strategic and technical leadership skills and leads the development of skills in their area of accountability.', 'Promove a aplicação do conhecimento para apoiar os imperativos estratégicos. Desenvolve ativamente suas habilidades de liderança estratégica e técnica e lidera o desenvolvimento de habilidades em sua área de responsabilidade.'),
('learning', 7, 'Inspires a learning culture to align with business objectives. Maintains strategic insight into contemporary and emerging industry landscapes. Ensures the organisation develops and mobilises the full range of required skills and capabilities. SFIA week announcement SFIA week 2026 - a diverse programme of free to attend activities and events created to help you SFIA version 9 Framework status: Current standard', 'Inspira uma cultura de aprendizado para alinhar-se aos objetivos comerciais. Mantém uma visão estratégica dos cenários contemporâneos e emergentes do setor. Garante que a organização desenvolva e mobilize toda a gama de habilidades e capacidades necessárias. Versão SFIA 9 Status da estrutura: Padrão atual'),
('planning', 1, 'Confirms required steps for individual tasks.', 'Confirma as etapas necessárias para tarefas individuais.'),
('planning', 2, 'Plans own work within short time horizons in an organised way.', 'Planeja seu próprio trabalho em prazos curtos e de forma organizada.'),
('planning', 3, 'Organises and keeps track of own work (and others where needed) to meet agreed timescales.', 'Organiza e mantém o controle do próprio trabalho (e de outros, quando necessário) para cumprir os prazos acordados.'),
('planning', 4, 'Plans, schedules and monitors work to meet given personal and/or team objectives and processes, demonstrating an analytical approach to meet time and quality targets.', 'Planeja, programa e monitora o trabalho para atender a determinados objetivos e processos pessoais e/ou da equipe, demonstrando uma abordagem analítica para cumprir metas de tempo e qualidade.'),
('planning', 5, 'Analyses, designs, plans, establishes milestones, and executes and evaluates work to time, cost and quality targets.', 'Analisa, projeta, planeja, estabelece marcos, executa e avalia o trabalho de acordo com metas de tempo, custo e qualidade.'),
('planning', 6, 'Initiates and influences strategic objectives and assigns responsibilities.', 'Inicia e influencia os objetivos estratégicos e atribui responsabilidades.'),
('planning', 7, 'Plans and leads at the highest level of authority over all aspects of a significant area of work. SFIA week announcement SFIA week 2026 - a diverse programme of free to attend activities and events created to help you SFIA version 9 Framework status: Current standard', 'Planeja e lidera, no mais alto nível de autoridade, todos os aspectos de uma área de trabalho significativa. Versão SFIA 9 Status da estrutura: Padrão atual'),
('problem', 1, 'Works towards understanding the issue and seeks assistance in resolving unexpected problems.', 'Trabalha para entender o problema e busca ajuda para resolver problemas inesperados.'),
('problem', 2, 'Investigates and resolves routine issues.', 'Investiga e resolve problemas de rotina.')
INSERT INTO sfia_atributo_nivel (slug, nivel, descricao_en, descricao_pt) VALUES
('problem', 3, 'Applies a methodical approach to investigate and evaluate options to resolve routine and moderately complex issues.', 'Aplica uma abordagem metódica para investigar e avaliar opções para resolver problemas rotineiros e moderadamente complexos.'),
('problem', 4, 'Investigates the cause and impact, evaluates options and resolves a broad range of complex issues.', 'Investiga a causa e o impacto, avalia as opções e resolve uma ampla gama de problemas complexos.'),
('problem', 5, 'Investigates complex issues to identify the root causes and impacts, assesses a range of solutions, and makes informed decisions on the best course of action, often in collaboration with other experts.', 'Investiga questões complexas para identificar as causas básicas e os impactos, avalia uma série de soluções e toma decisões informadas sobre o melhor curso de ação, muitas vezes em colaboração com outros especialistas.'),
('problem', 6, 'Anticipates and leads in addressing problems and opportunities that may impact organisational objectives, establishing a strategic approach and allocating resources.', 'Antecipa e lidera a abordagem de problemas e oportunidades que podem afetar os objetivos organizacionais, estabelecendo uma abordagem estratégica e alocando recursos.'),
('problem', 7, 'Manages inter-relationships between impacted parties and strategic imperatives, recognising the broader business context and drawing accurate conclusions when resolving problems. SFIA week announcement SFIA week 2026 - a diverse programme of free to attend activities and events created to help you SFIA version 9 Framework status: Current standard', 'Gerencia as inter-relações entre as partes afetadas e os imperativos estratégicos, reconhecendo o contexto comercial mais amplo e tirando conclusões precisas ao resolver problemas. Versão SFIA 9 Status da estrutura: Padrão atual'),
('security', 1, 'Develops an understanding of the rules and expectations of their role and the organisation.', 'Desenvolve o entendimento das regras e expectativas de sua função e da organização.'),
('security', 2, 'Has a good understanding of their role and the organisation’s rules and expectations.', 'Tem um bom entendimento de sua função e das regras e expectativas da organização.'),
('security', 3, 'Applies appropriate professionalism and working practices and knowledge to work.', 'Aplica profissionalismo, práticas de trabalho e conhecimento adequados ao trabalho.'),
('security', 4, 'Adapts and applies applicable standards, recognising their importance in achieving team outcomes.', 'Adapta e aplica os padrões aplicáveis, reconhecendo sua importância para alcançar os resultados da equipe.'),
('security', 5, 'Contributes proactively to the implementation of professional working practices and helps promote a supportive organisational culture.', 'Contribui proativamente para a implementação de práticas profissionais de trabalho e ajuda a promover uma cultura organizacional de apoio.'),
('security', 6, 'Takes a leading role in promoting and ensuring appropriate culture and working practices, including the provision of equal access and opportunity to people with diverse abilities.', 'Assume um papel de liderança na promoção e garantia de cultura e práticas de trabalho apropriadas, incluindo o fornecimento de acesso e oportunidades iguais para pessoas com habilidades diversas.'),
('security', 7, 'Provides clear direction and strategic leadership for embedding compliance, organisational culture, and working practices, and actively promotes diversity and inclusivity. SFIA week announcement SFIA week 2026 - a diverse programme of free to attend activities and events created to help you SFIA version 9 Framework status: Current standard', 'Fornece direção clara e liderança estratégica para incorporar a conformidade, a cultura organizacional e as práticas de trabalho, além de promover ativamente a diversidade e a inclusão. Versão SFIA 9 Status da estrutura: Padrão atual')
